export function syncFacts(s: SyncState, now = Date.now()): { text: string; tone?: "warn" }[] {
  const waiting = capAfterNumber(s.queued === 1 ? "1 change waiting" : `${s.queued} changes waiting`);
  const synced = s.lastSyncedAt === null ? null : `Last synced ${syncedAgo(s.lastSyncedAt, now)}`;
  if (!s.online) return s.queued > 0 ? [{ text: "Offline", tone: "warn" }, { text: waiting, tone: "warn" }] : [{ text: "Offline", tone: "warn" }];
  if (s.queued > 0) return synced ? [{ text: waiting, tone: "warn" }, { text: synced }] : [{ text: waiting, tone: "warn" }];
  return [{ text: synced ?? "Nothing waiting" }];
}
